          "type": "extended",
          "marks": 10,
          "answer": "An effective summary should first identify the article as an original research article and state its aim and study design, including sample sizes and comparison groups (e.g., 208 SARS-CoV-2-infected individuals vs 69 healthy controls). It should outline the key methods (e.g., ELISA for sP2X7 and CRP; luminescence-based multiplex assay for cytokines), then report the main findings (sP2X7, CRP and cytokines IL-1 receptor antagonist, IL-6, IL-15 and IL-18 were elevated in COVID-19; sP2X7 and CRP tracked disease severity; sP2X7 correlated with CRP and cytokines) and any supporting mechanistic evidence (ATP-stimulated release of IL-1beta and sP2X7 from LPS-stimulated peripheral blood mononuclear leukocytes, linking inflammasome activation to sP2X7 release). Critical evaluation is also expected - noting limitations (or their absence) and strengths such as sample size - before stating the authors' conclusion (circulating sP2X7 as a novel biomarker of COVID-19 severity) and the article's relevance to the chosen topic. The annotated bibliography develops scientific writing skills by requiring students to distinguish publication types, search and select relevant peer-reviewed literature (at least 7 original research and no more than 3 review articles among 12), write concisely to strict word limits, apply a consistent Harvard referencing style, work collaboratively with declared contributions, and use GenAI appropriately with disclosure, verification and evaluative judgment. It is worth 10% of the final mark and aligns to the subject learning outcome on demonstrating literature research skills and communicating findings in writing."
