          "answer": "Lactate is transported via the bloodstream to the liver, where it is taken up and converted back to glucose via gluconeogenesis. The glucose is then released into the bloodstream and transported back to the tissues. This shuttling of lactate from muscle to liver and glucose back to muscle is the Cori cycle.",
