          "topic": "respiration",
          "ai": true,
          "question": "Trace the path of a single glucose molecule through glycolysis and the TCA cycle. State the main products of one turn of the TCA cycle, explain their significance in cellular respiration, and give the net gain in ATP, NADH, FADH2 and GTP for one glucose molecule, accounting for the fact that the pathway runs twice per glucose.",
          "type": "extended",
          "marks": 10,
          "answer": "One glucose undergoes glycolysis in the cytoplasm to yield 2 pyruvate, with a net gain of 2 ATP and 2 NADH. Each pyruvate enters the mitochondrial matrix and is oxidatively decarboxylated by the pyruvate dehydrogenase complex (co-factors TPP, lipoyllysine, FAD, CoA and NAD+) to acetyl-CoA. Each acetyl-CoA condenses with oxaloacetate (citrate synthase) and proceeds through one turn of the TCA cycle (citrate → isocitrate → α-ketoglutarate → succinyl-CoA → succinate → fumarate → malate → oxaloacetate), occurring in the mitochondrial matrix. One turn yields 3 NADH (isocitrate dehydrogenase, α-ketoglutarate dehydrogenase, malate dehydrogenase), 1 FADH2 (succinate dehydrogenase) and 1 GTP (succinyl-CoA synthetase, via substrate-level phosphorylation). The NADH and FADH2 carry electrons to the respiratory transport chain to generate ATP via oxidative phosphorylation, which yields far more ATP than glycolysis alone. Because two pyruvate are produced per glucose, the TCA cycle turns twice, giving a net yield per glucose (glycolysis + TCA, excluding PDC and oxidative phosphorylation) of 2 ATP, 10 NADH, 2 FADH2 and 2 GTP.",
          "explanation": "Award marks for: glycolysis location and net yield; PDC reaction in the matrix; TCA cycle intermediates/enzymes; per-turn products (3 NADH, 1 FADH2, 1 GTP); role of NADH/FADH2 in oxidative phosphorylation; correct doubling and net totals (2 ATP, 10 NADH, 2 FADH2, 2 GTP)."
