          "answer": "Uncoupling proteins (e.g., UCP1 in brown fat) and chemical uncouplers (e.g., DNP, FCCP) provide an alternative route for protons to return from the intermembrane space to the matrix without passing through ATP synthase. This dissipates the proton-motive force as heat, so electron transport continues but the energy of the gradient is no longer conserved as ATP (uncoupling of oxidation from phosphorylation). Functions include: thermogenesis (heat production, e.g., UCP1 in brown adipose tissue); metabolic regulation (allowing oxidation of reduced carriers when ATP demand is low); and limiting reactive oxygen species by lowering the membrane potential. A full answer should link the mechanism to chemiosmotic coupling and note the trade-off between ATP yield and heat production.",
