          "type": "extended",
          "marks": 9,
          "answer": "In GPCR signalling, epinephrine (a water-soluble hormone) binds to a specific receptor on the outer surface of the target cell. The activated receptor engages the transducer, a G protein, which in turn activates an effector enzyme (e.g., adenylyl cyclase). The effector produces a second messenger (e.g., cAMP) inside the cell, which propagates and amplifies the signal to elicit the cellular response, such as mobilising fuel in the fight-or-flight response. This cascade allows amplification of the original hormone signal and rapid regulation, since second messengers and the hormone itself are quickly degraded. By contrast, the insulin receptor is a receptor tyrosine kinase (the same class used by growth receptors): rather than acting through a separate G protein transducer, the receptor itself possesses kinase activity and is activated upon insulin binding, triggering phosphorylation-based downstream signalling cascades. In both cases, a water-soluble hormone binds a cell-surface receptor and the message is transduced into intracellular signals, but the GPCR route relies on a G protein transducer, effector enzyme and second messenger, whereas the receptor tyrosine kinase transduces via receptor autophosphorylation.",
