          "answer": "Glycogen synthase is regulated by covalent modification: phosphorylation, catalysed by glycogen synthase kinase 3 (GSK3), converts it to the inactive form, while dephosphorylation by phosphoprotein phosphatase 1 (PP1) converts it back to the active form. Allosterically, glycogen synthase is activated by glucose 6-phosphate and glucose, so abundant glucose and its metabolite directly stimulate glycogen synthesis. Hormonally, insulin, glucagon and epinephrine regulate the pathway in response to glucose availability: insulin promotes the active, dephosphorylated state (inhibiting GSK3 and activating PP1), whereas glucagon and epinephrine promote phosphorylation cascades that inhibit glycogen synthase, suppressing glycogen synthesis when blood glucose is low or during the fight-or-flight response."
