          "answer": "Oxidation of organic molecules results in loss of electrons, and reduction results in gain of electrons. Practically, oxidation occurs if the number of C-H bonds decreases, and reduction occurs if the number of C-H bonds increases. When a molecule loses an electron it often simultaneously loses a proton (H+), e.g., AH → A + e- + H+, and the reverse applies for reduction.",
