          "answer": "Rubisco evolved before photosynthetic organisms raised atmospheric O2, so there was no selection pressure for it to discriminate between CO2 and O2; it therefore fixes both, at a ratio of about 4:1 CO2:O2. Its oxygenase activity produces metabolically useless 2-phosphoglycolate. Salvaging 2-phosphoglycolate is a complex process spanning chloroplast stroma, peroxisomes and mitochondria, requiring energy and consuming O2 at two points. Carbon is lost as CO2 without any energy production, undoing the work of photosynthesis.",
