          "type": "extended",
          "marks": 10,
          "answer": "(a) Energy production: catabolism of amino acids yields seven major carbon-skeleton products that enter central metabolism. Most amino acids do not enter the TCA cycle directly; their skeletons feed the TCA cycle, gluconeogenesis or ketogenesis. Amino acid catabolism accounts for only 10–15% of energy production, since glycolysis and fatty acid oxidation are more active. (b) Synthesis: amino acids are precursors to proteins, nucleotides, porphyrins, creatine, rigid polymers and polyamines. Neurotransmitter synthesis (dopamine, norepinephrine, epinephrine, GABA, histamine, serotonin) proceeds via a PLP-dependent decarboxylation; GABA dysregulation is linked to many disorders, histamine mediates vasodilation/sleep-wake regulation/gastric acid release, and serotonin affects mood, cognition, reward, learning, memory, vomiting and vasoconstriction. Glutathione (GSH), present at high amounts in most cells, is a reducing agent/antioxidant that keeps proteins and metal cations reduced, keeps redox enzymes reduced, and removes toxic reactive oxygen species (ROS). Nitric oxide (NO), discovered in the mid-1980s to act in neurotransmission, blood pressure regulation, blood clotting and immunity, is synthesised from arginine by nitric oxide synthase using NADPH.",
