          "type": "extended",
          "marks": 8,
          "answer": "An activation mixture of phosphate buffer, chymotrypsinogen and trypsin is prepared and sampled at t = 0, 15 and 30 min (tubes 1-3). Each sample receives trypsin inhibitor so residual trypsin cannot digest casein, then incubated with casein for 20 min at 37°C. Only if trypsin has converted chymotrypsinogen into active chymotrypsin will casein be hydrolysed; increasing activation time should yield progressively more hydrolysis. TCA is added to stop the reaction and precipitate undigested intact proteins; after 15 min at room temperature and centrifugation, the precipitate is scored (+ to 4+) with less precipitate indicating more digestion. The supernatant, containing digested polypeptides, is quantified by the Lowry protein assay read at 750 nm (row H provides the background control), with higher absorbance indicating more digested protein. The controls validate the interpretation: tube 4 (chymotrypsinogen + inhibitor) shows the zymogen alone is inactive; tube 5 (trypsin + inhibitor) shows trypsin blocked by inhibitor cannot digest casein; tube 6 (trypsin without inhibitor) shows active trypsin does digest casein, demonstrating the inhibitor works; and tube 7 (buffer only) shows casein is stable without enzyme. Together, increasing digestion across tubes 1-3 despite the presence of trypsin inhibitor proves that trypsin-activated chymotrypsin, not trypsin itself, is hydrolysing casein.",
