          "question": "Explain what the editorial means by guarding against 'building a story around preferred but not validated hypotheses', and state the one writing principle the editorial says should always be followed.",
          "type": "short",
          "marks": 3,
          "answer": "Authors must step back and critically evaluate the conclusions that can actually be drawn from the collected data rather than framing the narrative around results they wish were true. The text should stay true to the data, even though data need not be presented dryly or in chronological order of the experiments. The overarching principle is that the data should always be the lodestar.",
