          "question": "What functions should the introduction of a paper serve, and how should conflicting findings or controversies in the field be handled?",
          "type": "short",
          "marks": 4,
          "answer": "The introduction should introduce the main question the paper seeks to answer, provide context by covering the relevant literature, and through this present the rationale and objectives of the study. It should be selective and concise, synthesising the most pertinent primary research rather than exhaustively discussing every related paper. It must let a non-expert understand the broader topic, the key prior art and the specific questions addressed, while conveying why those questions matter and sparking interest. Conflicting findings, controversies and similar published conclusions should be presented clearly and addressed head-on, not avoided.",
          "explanation": "This requires staying up to date with the literature and compiling a comprehensive reference list that is whittled down to the essential references as writing progresses."
