          "type": "short",
          "marks": 4,
          "answer": "First pass metabolism is the reduction of a drug's concentration before it reaches the systemic circulation, because the drug is absorbed and metabolised by the liver. It is critical in drug design because it determines the final concentration available (bioavailability) and hence how effective the compound will be. If a drug is metabolised too much on first pass it may not achieve its intended effect (low efficacy). A drug whose target is liver enzymes might also alter the first-pass metabolism of other drugs, and an oral drug with limited efficacy may need to bypass the liver, for example via the intravenous route.",
