          "answer": "'A great deal of research has been conducted on the basic techniques of nuclear transfer, but few experiments have been carried out to discover the most appropriate age of the cytoplasm to support nuclear transfer most effectively.' The first clause asserts positive currency (a firm research foundation exists), while the second asserts negative currency (insufficient relevant work has been done). The reader infers that the writer believes more experiments are necessary — the phrase 'but few experiments' emphasises the research gap.",
