          "topic": "gluconeogenesis-glycogen",
          "ai": true,
          "question": "Explain how the activity of FBPase-1 is regulated and the implications of this regulation for glycolysis and gluconeogenesis.",
          "type": "short",
          "marks": 4,
          "answer": "FBPase-1 is allosterically inhibited in two ways. (1) AMP inhibits FBPase-1: when energy levels are low (higher ADP/AMP relative to ATP), the cell needs to generate energy, so inhibiting FBPase-1 causes fructose 1,6-bisphosphate to accumulate, favouring glycolysis. (2) Fructose 2,6-bisphosphate (F2,6BP) also inhibits FBPase-1, again causing fructose 1,6-bisphosphate accumulation and promoting glycolysis when glucose is plentiful. In both cases gluconeogenesis is suppressed while glycolysis is stimulated, ensuring the two opposing pathways are reciprocally regulated.",
