          "topic": "gluconeogenesis-glycogen",
          "ai": true,
          "question": "Describe how glycogen synthase is regulated between its active and inactive forms. Name the enzymes responsible for interconversion and discuss the allosteric and hormonal regulators involved, including the roles of insulin, glucagon and epinephrine.",
          "type": "extended",
          "marks": 8,
          "answer": "Glycogen synthase exists in two interconvertible forms: phosphorylation renders it inactive, while dephosphorylation renders it active. Enzyme 1, glycogen synthase kinase 3 (GSK3), phosphorylates glycogen synthase, converting it to the inactive form. Enzyme 2, phosphoprotein phosphatase 1 (PP1), dephosphorylates glycogen synthase, returning it to the active form. Allosterically, glucose 6-phosphate and glucose activate glycogen synthase, directly linking synthase activity to glucose availability. Hormonally, insulin, glucagon and epinephrine regulate the enzyme: insulin promotes the active, dephosphorylated state (stimulating glycogen synthesis when glucose is abundant), while glucagon and epinephrine favour the phosphorylated, inactive state (suppressing synthesis when glucose is scarce or during fight-or-flight). This coordinate hormonal control ensures glycogen synthesis and degradation are balanced against the amount of glucose available.",
