          "id": "biol214-auto-mtxncj29-n0",
          "title": "PKU Pre-laboratory Tutorial",
          "source": "auto-synced from Moodle",
          "added": "2026-09-12",
          "body": "This pre-lab covers **phenylketonuria (PKU)**, an **inborn error of metabolism** caused by a genetic defect in **phenylalanine hydroxylase**, leading to buildup of **phenylalanine** and **phenylpyruvate**, impaired neurological development, and management via a Phe-restricted diet (including avoiding artificial sweeteners) with non-Phe protein supplementation. Normal blood Phe is **1.3–2.0 mg/dL** versus ~**20 mg/dL** in untreated PKU, with treatment goals of **6 mg/dL** (children 0–8) and **12 mg/dL** (older children/adults). Screening evolved from the **Guthrie bacterial inhibition assay** (1960s) to **tandem mass spectrometry**, which detects 50+ disorders from a 3 mm dried blood spot in ~2 minutes. The practical quantifies Phe using **phenylalanine ammonium lyase (PAL)**, which converts Phe to **trans-cinnamate** measured at **290 nm**, with 0–40 mg/dL standards prepared via **C1V1 = C2V2** in 200 mM Tris-HCl. Corrected absorbances (Series 2 with PAL minus Series 1 without PAL, then 30 min minus 0 min) are plotted as a **standard curve** to interpolate unknown serum Phe concentrations.",
