          "id": "biol214-auto-mtxnfu4g-n0",
          "title": "Enzymes of the TCA Cycle - Pre-Lab Tutorial (SDH & MDH)",
          "source": "auto-synced from Moodle",
          "added": "2026-09-12",
          "body": "This pre-lab prepares the yeast practical that measures **succinate dehydrogenase (SDH)** and **malate dehydrogenase (MDH)** in subcellular fractions obtained by **differential centrifugation** (3,000 rpm pellets debris/nuclei; 12,000 rpm pellets mitochondria, leaving **cytosol** with microsomes and ribosomes). Yeast metabolism is **compartmentalised**: glycolysis is cytoplasmic, pyruvate enters via the **MPC** and is converted to acetyl-CoA by **PDH**, and the TCA cycle and **oxidative phosphorylation** are mitochondrial. SDH activity is followed as a decrease in **A600** as it reduces **DCPIP** via **PMS**, with **KCN** blocking Complex IV to divert electrons; MDH activity is followed as a decrease in **A340** from **NADH** oxidation, with excess NADH driving the reaction towards malate. Analysis uses blank-corrected slopes, the **Beer-Lambert law** (C = delta-A/(epsilon*l)), enzyme activity a = r x V, and **specific activity** = activity per mg protein (adjusting for the 1:5 diluted mitochondrial MDH fraction). Expected results: SDH only in mitochondria; MDH in both mitochondria and cytosol.",
