          "source": "auto-synced from Moodle",
          "added": "2026-09-12",
          "body": "This file is not biochemistry course content; it is a directory of University of Wollongong support services for BIOL214 students. **Student Central** is the primary administrative contact and the place to learn **academic consideration** rules via askUOW. Academic support centres on **Learning Development**, which offers free **academic writing and maths/stats consultations** and seminars bookable through the **Learning Co-op**, plus individual consultations with lecturers across campuses, and thesis writing support via the **Graduate Research School**. For quick help, **Studiosity** provides 24/7 short question chats and draft feedback through the subject Moodle page. **Academic integrity** is framed as the student's personal responsibility, with specific guidance on **AI tools such as ChatGPT**. Further services include the **Woolyungah Indigenous Centre**, **UOWx** extracurriculars, the **Library**, **Careers Central**, **Support Services**, and **Student Life**.",
